package com.finsight;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.*;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.CsvSource;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.test.mock.mockito.*;
import org.springframework.context.annotation.Import;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.test.context.*;
import org.springframework.test.web.servlet.MockMvc;
import java.math.BigDecimal;
import java.time.*;
import java.util.*;
import static org.assertj.core.api.Assertions.*;
import static org.mockito.Mockito.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@SpringBootTest @AutoConfigureMockMvc @ActiveProfiles("test")
@ContextConfiguration(initializers=IsolatedDatabaseGuard.class) @Import(RecurringApiTest.TestClockConfig.class)
class SpendingApiTest {
 @Autowired SpendingService spending;@Autowired RecurringApiTest.MutableClock clock;@Autowired JdbcTemplate jdbc;@Autowired MockMvc mvc;@Autowired ObjectMapper json;
 @SpyBean FinanceService finance;@MockBean SpendingAiClient ai;@Autowired RecurringRuleService rules;@Autowired PlannedTransactionService plans;@Autowired ForecastService forecast;
 @BeforeEach void setup(){clean();clock.date("2026-10-15");jdbc.update("UPDATE accounts SET starting_balance=1000 WHERE id=?",DemoIdentity.ACCOUNT_ID);when(ai.analyze(any())).thenReturn(Optional.empty());}
 @AfterEach void clean(){for(String t:List.of("planned_transactions","forecast_preferences","recurring_prediction_feedback","recurring_occurrences","recurring_rules","category_prediction_feedback","category_predictions","transactions"))jdbc.update("DELETE FROM "+t);}
 UUID category(String name){return jdbc.queryForObject("SELECT id FROM categories WHERE user_id=? AND name=?",UUID.class,DemoIdentity.USER_ID,name);}
 ApiModels.TransactionView add(String amount,String type,String category,String date){return finance.create(new ApiModels.TransactionInput("Synthetic expense",new BigDecimal(amount),TransactionType.valueOf(type),category(category),LocalDate.parse(date),null));}
 SpendingModels.Report report(String range){return spending.report(spending.period(range,null,null));}
 @Test void exactTotalsSharesIncomeNetAndEvidence(){add("0.10","EXPENSE","Groceries","2026-10-01");add("0.20","EXPENSE","Groceries","2026-10-02");add("0.70","EXPENSE","Shopping","2026-10-03");add("5.00","INCOME","Salary","2026-10-04");var r=report("this_month");assertThat(r.summary().expenses()).isEqualTo("1.00");assertThat(r.summary().income()).isEqualTo("5.00");assertThat(r.summary().net()).isEqualTo("4.00");assertThat(r.categories().getFirst().share()).isEqualTo("70.00");assertThat(r.summary().largestCategory()).isEqualTo("Shopping");assertThat(r.months().getFirst().partial()).isTrue();assertThat(r.evidence()).allMatch(e->e.amount().matches("\\d+\\.\\d{2}"));}
 @ParameterizedTest @CsvSource({"this_month,2026-10-01,2026-10-15","last_month,2026-09-01,2026-09-30","last_3,2026-08-01,2026-10-15","last_6,2026-05-01,2026-10-15","last_12,2025-11-01,2026-10-15"})
 void datePresets(String name,String from,String to){var p=spending.period(name,null,null);assertThat(p.from()).isEqualTo(LocalDate.parse(from));assertThat(p.to()).isEqualTo(LocalDate.parse(to));assertThat(java.time.temporal.ChronoUnit.DAYS.between(p.from(),p.to())).isEqualTo(java.time.temporal.ChronoUnit.DAYS.between(p.comparisonFrom(),p.comparisonTo()));}
 @Test void customRangeIncludesBoundariesAndExcludesFutureAndOtherDates(){add("1","EXPENSE","Groceries","2026-09-30");add("2","EXPENSE","Groceries","2026-10-01");add("3","EXPENSE","Groceries","2026-10-05");add("4","EXPENSE","Groceries","2026-10-06");add("100","EXPENSE","Groceries","2026-10-20");var r=spending.report(spending.period("custom",LocalDate.parse("2026-10-01"),LocalDate.parse("2026-10-05")));assertThat(r.summary().expenses()).isEqualTo("5.00");assertThat(r.summary().currentMonthSpending()).isEqualTo("9.00");}
 @Test void monthToDateUsesPriorMatchedDaysNotWholePriorMonth(){add("100","EXPENSE","Groceries","2026-09-10");add("900","EXPENSE","Groceries","2026-09-20");add("118","EXPENSE","Groceries","2026-10-10");var r=report("this_month");assertThat(r.summary().monthToDate().previous()).isEqualTo("100.00");assertThat(r.summary().monthToDate().percent()).isEqualTo("18.00");}
 @Test void averageNeedsThreeCompletedMonthsOfRecordedCoverage(){add("100","EXPENSE","Groceries","2026-07-01");add("200","EXPENSE","Groceries","2026-08-01");assertThat(report("this_month").summary().average().amount()).isNull();add("300","EXPENSE","Groceries","2026-09-01");add("999","EXPENSE","Groceries","2026-10-01");assertThat(report("this_month").summary().average().amount()).isEqualTo("200.00");}
 @Test void emptyDataAndZeroBaselineDoNotInventPercentages(){var r=report("this_month");assertThat(r.summary().largestCategory()).isNull();assertThat(r.summary().average().amount()).isNull();assertThat(r.summary().monthToDate().percent()).isNull();assertThat(r.insights()).isEmpty();assertThat(r.detection().status()).isEqualTo("insufficient");verify(ai,never()).analyze(any());}
 @Test void priorOnlyCategoriesDoNotBecomeLargestWithNoCurrentSpending(){add("20","EXPENSE","Groceries","2026-09-20");var r=report("this_month");assertThat(r.summary().largestCategory()).isNull();assertThat(r.insights()).noneMatch(i->i.id().startsWith("share-"));}
 @Test void grossExpensesDoNotInferRefundsAndCorrectionsUseCurrentLedger(){var expense=add("100","EXPENSE","Shopping","2026-10-01");add("20","INCOME","Salary","2026-10-02");assertThat(report("this_month").summary().expenses()).isEqualTo("100.00");finance.update(expense.id(),new ApiModels.TransactionInput("Corrected synthetic",new BigDecimal("50"),TransactionType.EXPENSE,expense.categoryId(),expense.date(),null));assertThat(report("this_month").summary().net()).isEqualTo("-30.00");finance.delete(expense.id());assertThat(report("this_month").summary().expenses()).isEqualTo("0.00");}
 @Test void zeroIncomeIsFactualNotAClaimAboutMissingBankActivity(){add("100","EXPENSE","Groceries","2026-10-01");var r=report("this_month");assertThat(r.insights()).anyMatch(i->i.id().equals("no-income")&&i.explanation().contains("does not infer"));}
 @Test void missingCategoryNamesUseExplicitFallback(){add("10","EXPENSE","Groceries","2026-10-01");doReturn(List.of()).when(finance).categories();assertThat(report("this_month").categories().getFirst().name()).isEqualTo("Unknown category");}
 @ParameterizedTest @CsvSource({"DAILY,10,304.37","WEEKLY,10,43.48","BIWEEKLY,10,21.74","TWICE_MONTHLY,10,20.00","MONTHLY,10,10.00","YEARLY,120,10.00"})
 void cadenceNormalization(String frequency,String amount,String expected){assertThat(SpendingService.normalize(new BigDecimal(amount),RecurrenceFrequency.valueOf(frequency))).isEqualByComparingTo(expected);}
 @Test void exactRecurringDatesDifferFromMonthlyEstimatesAndExcludePausedOrCanceled(){var r=rules.create(new RecurringModels.RuleInput("Synthetic weekly",new BigDecimal("10"),TransactionType.EXPENSE,category("Groceries"),RecurrenceFrequency.WEEKLY,null,null,LocalDate.parse("2026-10-16"),null,true,UUID.randomUUID(),false,null));var result=report("this_month");assertThat(result.recurring().normalizedMonthlyEstimate()).isEqualTo("43.48");assertThat(result.recurring().pendingThisMonth()).isEqualTo("30.00");assertThat(result.recurring().upcomingTotal()).isEqualTo("50.00");assertThat(result.recurring().recorded()).isEqualTo("0.00");r=rules.setEnabled(r.id(),new RecurringModels.StateInput(false,r.version()));assertThat(report("this_month").recurring().schedules()).isEmpty();rules.archive(r.id(),new RecurringModels.ArchiveInput(r.version()));assertThat(report("this_month").recurring().pendingThisMonth()).isEqualTo("0.00");}
 @Test void recordedRecurringPaymentLinkCountedOnceEvenWhenAlsoCompletingPlan(){var r=rules.create(new RecurringModels.RuleInput("Synthetic recurring",new BigDecimal("10"),TransactionType.EXPENSE,category("Groceries"),RecurrenceFrequency.MONTHLY,1,null,LocalDate.parse("2026-11-01"),null,true,UUID.randomUUID(),false,null));var t=add("10","EXPENSE","Groceries","2026-10-01");rules.reconcile(r.id(),new RecurringModels.ReconcileInput(LocalDate.parse("2026-11-01"),t.id(),false));var p=plans.create(new ForecastModels.PlanInput("Synthetic plan",new BigDecimal("10"),TransactionType.EXPENSE,t.categoryId(),LocalDate.parse("2026-11-01"),UUID.randomUUID()));plans.complete(p.id(),new ForecastModels.CompletionInput(ForecastModels.CompletionMode.LINK,t.id(),null,false,UUID.randomUUID(),p.version()));var result=report("this_month");assertThat(result.summary().expenses()).isEqualTo("10.00");assertThat(result.summary().recurringRecorded()).isEqualTo("10.00");assertThat(result.summary().nonrecurringRecorded()).isEqualTo("0.00");assertThat(result.recurring().upcomingTotal()).isEqualTo("0.00");}
 List<ApiModels.TransactionView> baseline(){List<ApiModels.TransactionView> rows=new ArrayList<>();for(int i=1;i<=8;i++)rows.add(add("10","EXPENSE","Groceries","2026-09-"+String.format("%02d",i)));return rows;}
 @Test void localStatisticalSignalsAreValidatedAndNumbersRecomputedFromLedger(){var history=baseline();var t=add("100","EXPENSE","Groceries","2026-10-05");when(ai.analyze(any())).thenReturn(Optional.of(new SpendingAiClient.Result("robust-mad-v1",8,1,0,List.of(new SpendingAiClient.Signal(t.id(),"CATEGORY_MAD",history.stream().map(ApiModels.TransactionView::id).toList())),false)));var r=report("this_month");var alert=r.insights().stream().filter(i->i.id().startsWith("unusual-")).findFirst().orElseThrow();assertThat(alert.amount()).isEqualTo("100.00");assertThat(alert.explanation()).contains("$60.00","$10.00","8 earlier");assertThat(alert.evidenceCount()).isEqualTo(9);}
 @Test void inventedOrIncompleteModelEvidenceIsRejectedWithoutBreakingFacts(){baseline();var t=add("100","EXPENSE","Groceries","2026-10-05");when(ai.analyze(any())).thenReturn(Optional.of(new SpendingAiClient.Result("robust-mad-v1",8,1,0,List.of(new SpendingAiClient.Signal(t.id(),"CATEGORY_MAD",List.of(UUID.randomUUID()))),false)));var r=report("this_month");assertThat(r.summary().expenses()).isEqualTo("100.00");assertThat(r.detection().status()).isEqualTo("unavailable");assertThat(r.insights()).noneMatch(i->i.id().startsWith("unusual-"));}
 @Test void serviceFailureDoesNotBreakDeterministicDashboard(){baseline();add("100","EXPENSE","Groceries","2026-10-05");var r=report("this_month");assertThat(r.detection().status()).isEqualTo("unavailable");assertThat(r.categories().getFirst().expenses()).isEqualTo("100.00");}
 @Test void completeCategoryAndGlobalMonthSurgesHaveTransparentBaselines(){for(String month:List.of("06","07","08"))add("100","EXPENSE","Groceries","2026-"+month+"-01");add("300","EXPENSE","Groceries","2026-09-01");var r=report("last_month");assertThat(r.insights()).anyMatch(i->i.id().equals("monthly-2026-09-null")&&i.calculations().stream().anyMatch(c->c.label().equals("Three-month median")&&c.value().equals("100.00")));assertThat(r.insights()).anyMatch(i->i.id().equals("monthly-2026-09-"+category("Groceries")));}
 @Test void analysisDoesNotWriteFinancePredictionsRulesPlansPreferencesOrBalances(){add("10","EXPENSE","Groceries","2026-10-01");var before=finance.list();var balance=finance.account();long pref=forecast.preferences().version();report("this_month");report("last_12");assertThat(finance.list()).isEqualTo(before);assertThat(finance.account()).isEqualTo(balance);assertThat(forecast.preferences().version()).isEqualTo(pref);for(String table:List.of("recurring_rules","planned_transactions","category_predictions","category_prediction_feedback"))assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM "+table,Integer.class)).isZero();}
 @Test void onlyFeatureIdsDatesAndCentsReachLocalAnalyzer()throws Exception{baseline();add("100","EXPENSE","Groceries","2026-10-05");report("this_month");var capture=org.mockito.ArgumentCaptor.forClass(SpendingAiClient.Input.class);verify(ai).analyze(capture.capture());String payload=json.writeValueAsString(capture.getValue());assertThat(payload).contains("amount_cents","category_id").doesNotContain("description","Synthetic expense","balance","email");}
 @Test void recordedPaymentChangesDoNotInventHistoricalSchedulePrices(){var rule=rules.create(new RecurringModels.RuleInput("Synthetic bill",new BigDecimal("10"),TransactionType.EXPENSE,category("Groceries"),RecurrenceFrequency.MONTHLY,1,null,LocalDate.parse("2026-11-01"),null,true,UUID.randomUUID(),false,null));var first=add("10","EXPENSE","Groceries","2026-09-01");var second=add("15","EXPENSE","Groceries","2026-10-01");rules.reconcile(rule.id(),new RecurringModels.ReconcileInput(LocalDate.parse("2026-11-01"),first.id(),false));rules.reconcile(rule.id(),new RecurringModels.ReconcileInput(LocalDate.parse("2026-12-01"),second.id(),true));var r=report("this_month");assertThat(r.recurring().changes()).hasSize(1);assertThat(r.recurring().changes().getFirst().percent()).isEqualTo("50.00");assertThat(r.insights()).anyMatch(i->i.id().startsWith("recurring-change-")&&i.explanation().contains("no historical schedule price"));}
 @Test void falseStatisticalFlagBelowRecomputedThresholdIsWithheld(){var history=baseline();var t=add("10.01","EXPENSE","Groceries","2026-10-05");when(ai.analyze(any())).thenReturn(Optional.of(new SpendingAiClient.Result("robust-mad-v1",8,1,0,List.of(new SpendingAiClient.Signal(t.id(),"CATEGORY_MAD",history.stream().map(ApiModels.TransactionView::id).toList())),false)));assertThat(report("this_month").detection().status()).isEqualTo("unavailable");}
 @Test void foreignRecordsCannotAffectFactsOrEvidence(){UUID user=UUID.randomUUID(),account=UUID.randomUUID(),cat=UUID.randomUUID();jdbc.update("INSERT INTO users(id,email,display_name) VALUES (?,?,?)",user,user+"@synthetic.local","Other");jdbc.update("INSERT INTO accounts(id,user_id,name,currency,starting_balance) VALUES (?,?,?,'USD',0)",account,user,"Other");jdbc.update("INSERT INTO categories(id,user_id,name,type) VALUES (?,?,?,'EXPENSE')",cat,user,"Other");jdbc.update("INSERT INTO transactions(id,user_id,account_id,category_id,description,amount,type,transaction_date) VALUES (?,?,?,?,?,999,'EXPENSE',DATE '2026-10-01')",UUID.randomUUID(),user,account,cat,"Foreign synthetic");assertThat(report("this_month").summary().expenses()).isEqualTo("0.00");assertThat(spending.transactions(spending.period("this_month",null,null),cat).transactions()).isEmpty();}
 @Test void apiValidationAndReadOnlyEvidenceEndpoint()throws Exception{add("10","EXPENSE","Groceries","2026-10-01");mvc.perform(get("/api/insights")).andExpect(status().isOk()).andExpect(jsonPath("$.summary.expenses").value("10.00"));mvc.perform(get("/api/insights/transactions").param("from","2026-10-01").param("to","2026-10-15")).andExpect(jsonPath("$.total").value(1)).andExpect(jsonPath("$.transactions[0].amount").value("10.00"));for(String range:List.of("unknown","custom"))mvc.perform(get("/api/insights").param("range",range)).andExpect(status().isBadRequest());mvc.perform(get("/api/insights").param("range","custom").param("from","2026-10-20").param("to","2026-10-10")).andExpect(status().isBadRequest());mvc.perform(get("/api/insights").param("range","custom").param("from","1800-01-01").param("to","2026-10-15")).andExpect(status().isBadRequest());}
}
